package com.prem.fileapp;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Date;
@Service public class JwtService{private final javax.crypto.SecretKey key;private final long secs;public JwtService(@Value("${security.jwt.secret}")String s,@Value("${security.jwt.access-token-seconds}")long x){if(s.length()<32)throw new IllegalArgumentException("JWT secret too short");key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));secs=x;}public String create(User u){Instant n=Instant.now();return Jwts.builder().subject(u.id).claim("username",u.username).claim("role",u.role).issuedAt(Date.from(n)).expiration(Date.from(n.plusSeconds(secs))).signWith(key).compact();}public String userId(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}
